userscript.function:

doServiceAjax('sepoa.svc.common.COMMON', 'CONNECTION', 'getActiveLanguage', void 0, function(so) {
    if (so.status != 1) {
        Alert(so.message);
        return;
    }

    var gridOptions = Sepoa.cache.grid.load(window.CONTEXT_NAME + '/resource/ux/admin/grid/AD_023.js');

    for (var key in gridOptions) {
        if(key.startsWith("ORG")) continue;
        gridOptions[key].COL_VISIBLE = 'true';
    }

    gridOptions['GRID_ID'].COL_WIDTH = '120';
    gridOptions['CODE'].COL_WIDTH = '100';
    gridOptions['CONTENTS'].COL_WIDTH = '360';
    gridOptions['COL_WIDTH'].COL_WIDTH = '100';
    gridOptions['COL_VISIBLE'].COL_WIDTH = '120';

    gridOptions['HOUSE_CODE'].COL_VISIBLE = 'false';
    gridOptions['GRID_ID'].COL_VISIBLE = 'false';

    var langCombo = Sepoa.cache.combo.get('SL0001,000#KO#AD001');
    var lang = Sepoa.cache.text.get("AD_023.CONTENTS");
    for (var idx in langCombo) {
        var item = langCombo[idx];

        if (item.value == Sepoa.info.LANGUAGE) {
            lang = item.text;
            break;
        }
    }

    gridOptions['CONTENTS'].CONTENTS = lang;

    gridObj = $sObject.gridObj = new SepoaDhtmlXGridObject(gridbox, 'gridObj', gridOptions);
    gridObj._onDnDFlag = true;
    gridObj.setGridDraw();
    gridObj.setSizes();
    gridObj.setDataOutput(dataOutput)
    gridObj.attachEvent('onTXE', doSaveEnd);
    gridObj.attachEvent('onDrop', onDrop);
    Sepoa.attachEvent('onLoad', function() {
        gridObj.setSizes();
    });
    SUX.attachEvent('onWindowResize', function() {
        gridbox.style.width = '';
        gridbox.style.height = '100%';
        gridObj.setSizes();
    });
}, false);


var m = gridObj.getRowsNum();
var nextSeq = 1;
for (var i = 0; i < m; i++) {
    var rid = gridObj.getRowId(i);
    if (!sUtils.string.toBoolean(gridObj.cells(rid, gridObj.getColIndexById('COL_VISIBLE')).getValue())) {
        seq = 9999
    } else if ((gridObj.cells(rid, gridObj.getColIndexById('COL_WIDTH')).getValue() || 0) <= 0) {
        seq = 9999
    } else {
        seq = nextSeq;
        nextSeq++;
    }
    gridObj.cells(gridObj.getRowId(i), gridObj.getColIndexById('COL_SEQ')).setValue(seq * 10);
}

gridObj.sortRows(gridObj.getColIndexById('COL_SEQ'));
gridObj.allRowsChecked('SELECTED', true);


if (item && item.grid_id) {
    dataOutput.setValue('GRID_ID', item.grid_id);
    dataOutput.setValue('HOUSE_CODE', item.house_code);

    gridObj.postConnection(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doQuery', 'PROCESS_ID=sepoa.svc.admin.AD_023']);
    if (!gridObj._fake) {
        gridObj.setSizes();
    }
} else {
    gridObj.clearAll(false);
}


var mode = obj.mode;
var status = obj.status;
var message = obj.message;

if (status != 'true') {
    Alert(message);
    return;
}

Alert(Sepoa.cache.text.get('MESSAGE.0001'));

Sepoa.cache.clear();


if (stage == 0) {
    return true;
} else if (stage == 1) {
    return true;
} else if (stage == 2) {
    return true;
}
return false;


        	if(gridObj.getRowsNum() == 0) {
        		Alert(Sepoa.cache.text.get('AD_023_2.MESSAGE_0001'));
        		return;
        	}

        	Confirm(Sepoa.cache.text.get('AD_023_2.MESSAGE_0002'), function(flag) {
        		if(flag) {
        			var replaceColumns = ['CONTENTS', 'COL_TYPE', 'NOT_NULL', 'COL_FORMAT', 'COL_WIDTH', 'COL_ALIGN', 'COL_SORT', 'COL_COLOR', 'COL_SEQ'];
		        	var selectedRowIDS = gridObj.getSelectedRows('COL_VISIBLE');

		        	for(var idx in selectedRowIDS) {
		        		var rID = selectedRowIDS[idx];

		        		for(var i in replaceColumns) {
		        			var cIn = gridObj.getColIndexById(replaceColumns[i]);
		        			var orgValue = gridObj.cells(rID, gridObj.getColIndexById('ORG_' + replaceColumns[i])).getValue();

		        			gridObj.cells(rID, cIn).setValue(orgValue);
		        		}
		        	}
        		}
        	});
